  var BODY = false;                /* 감상 중인가 */
  var BODYENT = null;              /* 지구 위에 선 기체 (Primitive Model) */
  var BODYWAIT = false;            /* 받는 중 — 5.4MB 라 몇 초 걸린다. 겹쳐 안 세우게 */
  var BODYWAS = false;             /* B 를 누르기 전의 OUT — 되돌릴 값 */
